// Deterministic normalization and provisional Demand Heat.
// This sandbox does not create a CRM lead or contact anyone.
function daysSince(value) {
  if (!value) return null;
  const t = Date.parse(value);
  if (!Number.isFinite(t)) return null;
  return Math.max(0, (Date.now() - t) / 86400000);
}
function freshnessScore(days) {
  if (days === null) return 0;
  if (days <= 1) return 25;
  if (days <= 3) return 18;
  if (days <= 7) return 10;
  return 0;
}
function urgencyScore(value) {
  if (!value) return 0;
  const days = (Date.parse(value) - Date.now()) / 86400000;
  if (!Number.isFinite(days)) return 0;
  if (days >= 0 && days <= 3) return 20;
  if (days <= 7 && days >= 0) return 15;
  if (days <= 14 && days >= 0) return 8;
  return 0;
}
function volumeScore(count) {
  const n = Number(count);
  if (!Number.isFinite(n) || n <= 0) return 0;
  if (n >= 10) return 20;
  if (n >= 5) return 16;
  if (n >= 2) return 10;
  return 5;
}
function canonicalize(url) {
  try {
    const u = new URL(url);
    u.hash = "";
    u.search = "";
    return u.toString().replace(/\/+$/, "");
  } catch {
    return String(url || "").trim().toLowerCase().replace(/[?#].*$/, "").replace(/\/+$/, "");
  }
}
return items.map(({ json }) => {
  const j = { ...json };
  const age = daysSince(j.published_at);
  const score = freshnessScore(age)
    + volumeScore(j.headcount)
    + urgencyScore(j.start_date)
    + (j.repeatable ? 15 : 0)
    + ((j.location && j.site_name) ? 10 : 0)
    + Math.min(10, Math.max(0, Number(j.source_reliability) || 0));
  const demandType = j.signal_kind || (Number(j.headcount) >= 5 ? "CREW_REQUEST" : "SINGLE_POSITION");
  return {
    json: {
      demo_only: true,
      source_id: j.source_id,
      source_permission: j.permission_status,
      company_name: j.company_name || null,
      company_inn: j.company_inn || null,
      buyer_role: j.buyer_role || "UNKNOWN",
      title: j.title || null,
      description_summary: String(j.description || "").slice(0, 500),
      canonical_url: canonicalize(j.canonical_url),
      location: j.location || null,
      headcount: Number(j.headcount) || null,
      start_date: j.start_date || null,
      demand_type: demandType,
      demand_heat: Math.min(100, score),
      confidence: "DEMO_ONLY_NOT_VALIDATED",
      hard_stops: [],
      review_required: true,
      send_enabled: false,
      dedup_key: [j.source_id, canonicalize(j.canonical_url)].join("|"),
      published_at: j.published_at || null,
      parsed_at: new Date().toISOString()
    }
  };
});
